-- Catálogo de departamentos — antes era una lista fija hardcodeada en
-- DepartamentosColombiaUtil.java (33 departamentos oficiales); pasa a vivir en la BD, con el mismo
-- criterio ya usado para países (V181), para que un admin pueda gestionarla (agregar/editar/
-- eliminar) sin desplegar código. Se siembra con los mismos 33 registros que tenía el código.
CREATE TABLE "departamentos" (
  "id_departamento" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "nombre" VARCHAR(100) NOT NULL UNIQUE,
  "codigo_dane" VARCHAR(2) NOT NULL UNIQUE
);

